"""Governance for the agents (generated by G2C for E2A v1.2; completed by hand): ordered stages
run for every agent (screening before it reads, approval after), and each agent's tool
allow-list, all built from policies/governance.yaml (services/policy.py).

  capacity      the in-flight limit (the free tier: few concurrent requests)
  token_budget  the request's token budget (max_token_budget: the Gemini free tier's)
  firewall      prompt-injection patterns and the length limit on the request
  entitlement   the caller's acting role must be entitled to the agent
  approval      an actionable proposal waits for a second person before ExecutionAgent acts
  redaction     IBANs, card numbers and e-mail addresses masked on the way out
"""
from e2a import (ApprovalStage, BaseGovernanceFramework, CapacityStage, FirewallStage, GovernanceRefusal,
                 InflightLimiter, IngressStage, RedactionStage, TokenBudgetStage)

from .policy import Policy


class EntitlementRefusal(GovernanceRefusal, PermissionError):
    code = 'ENTITLEMENT'


# the agent that serves an intent: the entitlement stage checks the caller's role for it
AGENT_FOR = {'INVESTIGATE': 'InvestigatorAgent', 'EXPLAIN': 'InvestigatorAgent', 'PROPOSE': 'ProposalAgent'}


class EntitlementStage(IngressStage):
    """The caller's acting role must be entitled to the agent that serves the request's intent
    (before routing: IntentAgent), and to ExecutionAgent once a proposal is actionable."""
    name = 'entitlement'

    def __init__(self, policy: Policy) -> None:
        self.policy = policy

    def check(self, state, ctx, messages):
        agent = 'ExecutionAgent' if actionable(state) else AGENT_FOR.get(state.get('intent'), 'IntentAgent')
        if state.get('role') not in self.policy.entitlements.get(agent, []):
            raise EntitlementRefusal(f"role '{state.get('role')}' may not use {agent}", self.name)
        return state


def actionable(state) -> bool:
    return state.get('intent') == 'PROPOSE' and (state.get('proposal') or {}).get('action') not in (None, 'NONE')


class ServiceGovernance(BaseGovernanceFramework):
    def __init__(self, policy: Policy = None) -> None:
        self.policy = policy or Policy()
        self.limiter = InflightLimiter(self.policy.max_inflight)

    @property
    def tool_policy(self):
        return self.policy.tools

    @property
    def stages(self):
        return [
            CapacityStage(self.limiter),
            TokenBudgetStage(),
            FirewallStage(self.policy.injection_patterns, self.policy.redaction, fields=('query',),
                          max_chars=self.policy.max_query_chars),
            EntitlementStage(self.policy),
            ApprovalStage(required=lambda state, ctx: actionable(state),
                          reason=f'an adjustment waits for a {self.policy.approver_role} (four eyes)'),
            RedactionStage(self.policy.redaction, fields=('text',)),
        ]
